#nullable enable // autogenerated

using MVZ2.Vanilla.Almanac;
using PVZEngine.Definitions;
using PVZEngine.Placements;

namespace MVZ2.GameContent.Placements
{
    [AutoPlacementDefinition(VanillaPlacementNames.amphibious)]
    public class AmphibiousPlacement : PlacementDefinition
    {
        public AmphibiousPlacement(string nsp, string name) : base(nsp, name, VanillaSpawnConditions.amphibious)
        {
            AddMethod(VanillaPlaceMethods.entity);
            AddMethod(VanillaPlaceMethods.firstAid);
            this.SetAlmanacTag(VanillaAlmanacTagID.placementAmphibious);
        }
    }
}
